<template><section class="coverage-section" :class="{'is-defensive':defensive}">
 <div class="coverage-key"><span>{{ defensive?'Quand tu reçois une attaque':'Quand tu attaques' }}</span><p>{{ defensive?'Repère les faiblesses, puis les partenaires qui peuvent encaisser.':'Analyse des quatre capacités équipées face à chaque type adverse.' }}</p></div>
 <div class="coverage-legend"><span v-for="label in defensive?['×4 / ×2 · Vulnérable','×½ / ×¼ · Résiste','×0 · Immunisé']:['×2 · Super efficace','×1 · Neutre','×½ / ×0 · Peu efficace ou nul']" :key="label">{{ label }}</span></div>
 <section v-for="group in groups" :key="group.title" class="coverage-group"><header><h4>{{ group.title }}</h4><small>{{ group.rows.length }} type{{ group.rows.length>1?'s':'' }}</small></header><div class="coverage-grid"><button v-for="row in group.rows" :key="row.type" :class="tone(row)" :aria-expanded="selected===row.type" @click="selected=selected===row.type?null:row.type" :data-coverage-type="row.type"><pokemon-type-icon :type="row.type"/><strong>{{ typeName(row.type) }}</strong><b>{{ value(row) }}</b><small>{{ caption(row) }}</small></button></div><p v-if="!group.rows.length" class="coverage-none">{{ defensive?'Aucun type dans cette catégorie.':'Aucun type dans cette catégorie avec ces capacités.' }}</p></section>
 <article v-if="details" class="coverage-details" role="status"><h4><pokemon-type-icon :type="details.type"/>{{ defensive?'Recevoir une attaque '+typeName(details.type):'Affronter le type '+typeName(details.type) }}</h4><p v-for="(p,i) in members" :key="p.uuid||i"><span>{{ p.name || p.truename || p.data?.name?.french }}</span><b :class="defensive?defenseTone(details.multipliers[i]):''">{{ defensive?format(details.multipliers[i])+' · '+defenseLabel(details.multipliers[i]):best(p,details.type) }}</b></p></article>
 <p class="coverage-note">{{ defensive?'Talents de type et mutations inclus. La météo, les talents adverses et les protections conditionnelles (Multiécaille, Fermeté, contact…) peuvent modifier les dégâts réels.':'Types simples, sans talent adverse. Un double type peut changer le résultat. Les capacités de statut sont exclues ; la puissance et le niveau ne sont pas évalués ici.' }}</p>
</section></template>
<script>
import PokemonTypeIcon from '../PokemonTypeIcon.vue';
import {individualOffense} from '@/services/teamCoverage';
import {localizeMoveName} from '@/services/i18n';
import {localizeTypeName} from '@/services/pokemonTypes';
export default{components:{PokemonTypeIcon},props:{analysis:Object,team:Array,defensive:Boolean},data:()=>({selected:null}),computed:{members(){return this.team.filter(p=>!p.isEgg);},rows(){return this.defensive?this.analysis.defense:this.analysis.offense;},details(){return this.rows.find(r=>r.type===this.selected);},groups(){const rows=this.rows;if(!this.defensive)return[{title:'Avantage offensif',rows:rows.filter(r=>r.best>1)},{title:'Dégâts neutres',rows:rows.filter(r=>r.best===1)},{title:'Couverture à compléter',rows:rows.filter(r=>r.best<1)}];return[{title:'Points de vigilance',rows:rows.filter(r=>r.weak>0)},{title:'Résistances et immunités',rows:rows.filter(r=>!r.weak&&r.resist+r.immune>0)},{title:'Dégâts neutres',rows:rows.filter(r=>!r.weak&&!r.resist&&!r.immune)}];}},watch:{defensive(){this.selected=null;}},methods:{typeName:localizeTypeName,format(n){return n===.5?'×½':n===.25?'×¼':'×'+String(n).replace('.',',');},defenseTone:n=>n>1?'text-danger':n<1?'text-good':'',defenseLabel:n=>n===0?'Immunité':n>1?'Faiblesse':n<1?'Résistance':'Neutre',best(p,t){const list=individualOffense(p,t);return list.length?this.format(list[0].multiplier)+' · '+localizeMoveName(list[0].name,'fr'):'Aucune attaque offensive';},value(r){return this.members.length===1?this.format(this.defensive?r.multipliers[0]:r.best):this.defensive?r.weak?`${r.weak} vulnérable${r.weak>1?'s':''}`:`${r.resist+r.immune} protégé${r.resist+r.immune>1?'s':''}`:r.count?`${r.count} réponse${r.count>1?'s':''} ×2`:'Meilleur : '+this.format(r.best);},caption(r){return this.defensive?this.members.length===1?this.defenseLabel(r.multipliers[0]):`${r.resist} résiste${r.resist>1?'nt':''} · ${r.immune} immunisé${r.immune>1?'s':''}`:this.members.length===1?r.best>1?'Super efficace':r.best===1?'Neutre':r.best>0?'Peu efficace':'Aucun dégât':r.count>=2?'Plusieurs partenaires':r.count===1?'Un seul partenaire':'Pas de super efficacité';},tone(r){return this.defensive?r.weak>0?'is-danger':r.immune+r.resist>0?'is-good':'is-neutral':r.count>=2?'is-good':r.count===1?'is-covered':r.best===1?'is-neutral':'is-danger';}}};
</script>
