ls h4 .pokemon-type-icon{width:24px;height:24px}.coverage-details p{margin:8px 0;display:flex;justify-content:space-between;gap:15px;font-size:11px;padding-bottom:8px;border-bottom:1px solid var(--journal-border)}.coverage-details p:last-child{border:0;padding-bottom:0}.coverage-details b{text-align:right;overflow-wrap:anywhere}.coverage-none{font-size:11px;color:var(--journal-muted)}.text-danger{color:var(--journal-danger,#ab6671)}.text-good{color:var(--journal-accent)}@media(max-width:650px){.coverage-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:7px}.coverage-grid button{min-height:108px;padding:9px 4px}.coverage-key>span{font-size:18px}.coverage-details p{font-size:10px}}
</style>
